  function startRequest(id) { const item = findItem(id); if (!item) return; requireAuth(() => { closeDialog($("#item-dialog")); $("#request-form").reset(); $("#request-item-id").value=item.id; $("#request-item-name").textContent=item.title; $("#request-quantity").max=String(item.quantity||1); $("#request-quantity").value="1"; $("#request-availability").textContent="בחרו תאריך ושעה כדי לבדוק זמינות."; $("#request-deposit-box").hidden=true; $("#request-deposit-consent").required=false; openDialog($("#request-dialog")); }); }
  let availabilityTimer;
  async function checkRequestedAvailability(){
    clearTimeout(availabilityTimer);
    const id=$("#request-item-id").value,from=$("#request-start").value,until=$("#request-end").value;
    if(!id||!from||!until){$("#request-availability").textContent="בחרו תאריך ושעה כדי לבדוק זמינות.";return;}
    availabilityTimer=setTimeout(async()=>{try{
      $("#request-availability").textContent="בודקים זמינות…";
      const data=await api(`/api/items/${encodeURIComponent(id)}/availability-check?from=${encodeURIComponent(from)}&until=${encodeURIComponent(until)}`);
      $("#request-quantity").max=String(Math.max(1,data.availableQuantity||1));
      $("#request-availability").textContent=data.available?`זמין בטווח שבחרתם — ${data.availableQuantity} יחידות זמינות.`:(data.nextAvailableAt?`לא זמין בטווח שבחרתם. הזמינות הקרובה שמצאנו מתחילה ב־${new Date(data.nextAvailableAt).toLocaleString("he-IL")}.`:"לא זמין בטווח שבחרתם."); $("#request-waitlist").hidden=Boolean(data.available);
      $("#request-deposit-box").hidden=!data.depositRequired; $("#request-deposit-consent").required=Boolean(data.depositRequired);
      $("#request-deposit-amount").textContent=(Number(data.depositAmountAgorot||0)/100).toFixed(2);
    }catch(error){$("#request-availability").textContent=error.message||"לא ניתן לבדוק זמינות כרגע.";}},180);
  }
