    if(row.direction==="outgoing"&&row.workflow_status==="pickup_expired") actions += `<button class="button button-primary button-small" data-pickup-expiry="wait" data-request-id="${escapeHTML(row.id)}">להמתין לתיאום חדש</button><button class="button button-secondary button-small" data-pickup-expiry="cancel" data-request-id="${escapeHTML(row.id)}">לבטל את הבקשה</button>`;
